python3 -c "
import json
with open('history/evolution_summary.jsonl') as f:
    lines=[json.loads(l) for l in f if l.strip()]
print(f\"{'it':>3} {'name':<26} {'avg':>7} {'USPTO':>7} {'Symptom':>8} {'LawBench':>9}  status\")
for e in lines:
    s=e.get('scores') or {}
    def g(k):
        v=s.get(k) or {}
        a=v.get('successful_accuracy', v.get('accuracy'))
        return f'{a:.3f}' if isinstance(a,(int,float)) else '  -  '
    print(f\"{e.get('iteration'):>3} {str(e.get('name'))[:26]:<26} {e.get('average',0):>7.4f} {g('USPTO'):>7} {g('Symptom2Disease'):>8} {g('LawBench'):>9}  {e.get('status')}\")
"

python3 -c "
import json
for name in ['uspto','symptom_diagnosis','crime_prediction']:
    for split in ['train','val']:
        try:
            with open(f'benchmark/data/{name}/{split}.jsonl') as f:
                rows=[json.loads(l) for l in f if l.strip()]
            print('===',name,split,len(rows))
            print(json.dumps(rows[0], ensure_ascii=False)[:700])
        except Exception as e: print(name,split,'ERR',e)
"

