"""Minimal SMILES parser + WL canonical certificate, for measurement only."""
import re, sys
from collections import defaultdict

ATOM_RE = re.compile(r"(\[[^\]]+\]|Cl|Br|[BCNOSPFI]|[bcnops]|[0-9]|%\d\d|\(|\)|=|#|\+|\\|/|\.|.)")

ELEMENTS = ["Cl", "Br", "B", "C", "N", "O", "S", "P", "F", "I",
            "b", "c", "n", "o", "p", "s"]

def parse(smiles):
    """Return (atoms, bonds) with atoms=[label,...], bonds=[(i,j,order)]."""
    s = smiles.strip()
    toks = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == "[":
            j = s.index("]", i)
            toks.append(s[i:j+1]); i = j + 1
        elif s[i:i+2] in ("Cl", "Br"):
            toks.append(s[i:i+2]); i += 2
        else:
            toks.append(c); i += 1
    atoms, bonds = [], []
    stack, rings = [], {}
    prev, pending = None, None
    for t in toks:
        if t == "(":
            stack.append(prev); continue
        if t == ")":
            prev = stack.pop(); continue
        if t in "-=#:+/\\":
            pending = {"-": 1, "=": 2, "#": 3, ":": 1.5, "/": 1, "\\": 1}[t]
            continue
        if t == ".":
            prev = None; continue
        if t.isdigit() or (t.startswith("%") and t[1:].isdigit()):
            key = int(t[1:]) if t.startswith("%") else int(t)
            if key in rings:
                other, order = rings.pop(key)
                if order is None:
                    order = pending if pending is not None else 1
                bonds.append((other, prev, order))
            else:
                rings[key] = (prev, pending)
            pending = None
            continue
        # atom
        label, chg = None, 0
        if t.startswith("["):
            body = t[1:-1]
            m = re.match(r"(\d+)?([A-Za-z][a-z]?)", body)
            if m:
                label = m.group(2)
                rest = body[m.end():]
                if rest.startswith("@"):
                    rest = rest.lstrip("@")
                mm = re.search(r"([+-])(\d*)", rest)
                if mm:
                    chg = (1 if mm.group(1) == "+" else -1) * int(mm.group(2) or 1)
            hn = body.count("H")
            mh = re.search(r"H(\d*)", body)
            hcount = int(mh.group(1) or 1) if mh else 0
        else:
            label = t
            hcount = None
        atoms.append((label, chg, hcount))
        idx = len(atoms) - 1
        if prev is not None:
            order = pending if pending is not None else 1
            bonds.append((prev, idx, order))
        prev = idx
        pending = None
    return atoms, bonds


def normalize_atom(a):
    label, chg, hcount = a
    if label.islower():
        return ("ar", label.upper(), chg)
    return ("al", label, chg)


def wl_certificate(smiles):
    """Weisfeiler-Lehman style canonical certificate of the molecular graph."""
    atoms, bonds = parse(smiles)
    n = len(atoms)
    if n == 0:
        return ()
    adj = defaultdict(list)
    for i, j, o in bonds:
        adj[i].append((j, o)); adj[j].append((i, o))
    labels = [normalize_atom(a) for a in atoms]
    cert = []
    for _ in range(n):
        cert.append(tuple(sorted(labels)))
        new = []
        for i in range(n):
            sig = tuple(sorted((labels[j], o) for j, o in adj[i]))
            new.append((labels[i], sig))
        # compress
        uniq = {v: k for k, v in enumerate(sorted(set(new), key=repr))}
        labels = [uniq[v] for v in new]
        if len(set(labels)) == n and len(cert) > 2:
            break
    cert.append(tuple(sorted(labels)))
    return tuple(map(repr, cert))


if __name__ == "__main__":
    for a, b in [("NNc1ccccc1", "c1ccccc1NN"),
                 ("COc1cccc(-c2cc(N)c(C(=O)O)s2)c1", "COc1cccc(-c2cc(N)c(C(=O)O)s2)c1"),
                 ("OB(O)c1ccc(Cl)cc1", "Clc1ccc(B(O)O)cc1")]:
        print(wl_certificate(a) == wl_certificate(b), a, "|", b)

