import json, sys, collections
sys.path.insert(0,'/tmp')
from smi import wl_certificate

rows=[json.loads(l) for l in open('history/results/samples.jsonl')]
def units(s): return sorted(u.strip().lower() for u in (s or '').strip().split('.') if u.strip())
def moleq(p,t):
    try:
        pu, tu = units(p), units(t)
        if len(pu)!=len(tu): return False
        return sorted(map(wl_certificate,pu))==sorted(map(wl_certificate,tu))
    except Exception as e:
        return None
for cand in ['sibling_units','formula_coverage','carry_offer','baseline']:
    sub=[r for r in rows if r['candidate']==cand and r['task']=='USPTO']
    wrong=[r for r in sub if not r['was_correct']]
    eq=sum(1 for r in wrong if moleq(r['prediction'],r['target']))
    tot=len(sub); corr=tot-len(wrong)
    print(f'{cand:<20} correct={corr}/{tot} ({corr/tot:.3f})  wrong={len(wrong)}  of which same-molecule={eq}  -> potential {(corr+eq)/tot:.3f}')
