import json, re, collections, sys

def load(p): return [json.loads(l) for l in open(p) if l.strip()]
def split_units(text, seps=(';',)):
    for s in seps:
        if s in text:
            return [p.strip() for p in text.split(s) if p.strip()]
    return [text.strip()] if text.strip() else []
def target_units(t):          # the evaluator's own reading
    return set(split_units(t, (';', '；', ',', '，', '、')))
def label_units(t):           # the corpus's own reading
    return set(split_units(t, (';',)))

train = load('benchmark/data/crime_prediction/train.jsonl')
train_labels = collections.Counter()
for r in train:
    a = r['answer']
    if 'answer' in r and '罪名' in a: a = a.split('罪名')[-1].lstrip(':：')
    for u in split_units(a.strip(), (';',)): train_labels[u] += 1
VOCAB = set(train_labels)

def pieces(u):
    """u split at the inner separator, as (unit, piece, is_separator) token list."""
    return u.split('、')

def insertion_extends(u, v):
    """v is u with one or more '、'-joined pieces inserted (both non-empty pieces)."""
    if u == v or u not in v:
        return False
    up = u.split('、')
    vp = v.split('、')
    # v's pieces must contain u's pieces as a subsequence, plus at least one extra,
    # and the rejoined text of the matched pieces must equal u piecewise.
    i = 0
    for p in vp:
        if i < len(up) and p == up[i]:
            i += 1
    return i == len(up) and len(vp) > len(up)

def proposals(u, carried):
    out = []
    for v in VOCAB:
        if v in carried:
            continue
        if insertion_extends(u, v):
            out.append(v)
    return out

