def _required_markup(question: str) -> list[str]:
    if not question:
        return []
    tags = re.findall(r"\[[^\[\]\s]{1,24}\]", question)
    tags += [f"<{name}>" for name in re.findall(r"<([A-Za-z_][A-Za-z0-9_]{0,11})>", question)]
