def _required_markup(question: str) -> list[str]:
    """The delimiters the question asks the answer to carry.

    A bracketed token is not a requirement merely by appearing in the question: a
    question carries bracketed notation of its own. A chemistry input is written in
    bracket atoms, so the earlier reading - every bracketed token in the question -
    asked the solver for markup the question never mentions ("the question asks for
    [nH], which is missing from the draft"), and a fact pattern can cite a year in
    brackets. Measured over the three training corpora, that reading invented a
    requirement on 9 of 30 free-form questions and on 2 of 200 set-answering ones;
    every invention is a defect the solver is told to fix. A token is a delimiter
    when the question *uses* it as one: it closes the token, or it names the token
    beside an angle-bracket wrapper, which is how a format example is written.
    """
    if not question:
        return []
    wrapped = set(re.findall(r"\[/([^\[\]\s/]{1,24})\]", question))
    angles = list(re.finditer(r"<([A-Za-z_][A-Za-z0-9_]{0,11})>", question))
    tags: list[str] = []

    def add(tag: str) -> None:
        if tag not in tags:
            tags.append(tag)

    for match in re.finditer(r"\[[^\[\]\s]{1,24}\]", question):
        name = match.group()[1:-1]
        if name.startswith("/"):
            if name[1:] in wrapped:
                add(match.group())
            continue
        if name in wrapped or any(
            abs(match.start() - angle.start()) <= MARKUP_NEAR for angle in angles
        ):
            add(match.group())
    for angle in angles:
        add(angle.group())
    return tags[:4]

